        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = history[history.length - 1].domainState || {};
            var finalRCS = ds.rcs || 0;
            var outcome = '';
            var insights = [];

            if (finalRCS >= 80) {
                outcome = window.mySimulation.t('outcome_commendation');
                insights.push(window.mySimulation.t('insight_commendation_1'));
                insights.push(window.mySimulation.t('insight_commendation_2'));
            } else if (finalRCS >= 65) {
                outcome = window.mySimulation.t('outcome_closure');
                insights.push(window.mySimulation.t('insight_closure_1'));
                insights.push(window.mySimulation.t('insight_closure_2'));
            } else if (finalRCS >= 50) {
                outcome = window.mySimulation.t('outcome_partial');
                insights.push(window.mySimulation.t('insight_partial_1'));
                insights.push(window.mySimulation.t('insight_partial_2'));
            } else if (finalRCS >= 35) {
                outcome = window.mySimulation.t('outcome_mou');
                insights.push(window.mySimulation.t('insight_mou_1'));
                insights.push(window.mySimulation.t('insight_mou_2'));
            } else {
                outcome = window.mySimulation.t('outcome_cease');
                insights.push(window.mySimulation.t('insight_cease_1'));
                insights.push(window.mySimulation.t('insight_cease_2'));
            }

            if ((ds.detectionRate || 0) < 60) insights.push(window.mySimulation.t('insight_low_detection'));
            if ((ds.falsePositiveRate || 0) > 90) insights.push(window.mySimulation.t('insight_high_fp'));
            if ((ds.kycProgress || 0) < 50) insights.push(window.mySimulation.t('insight_low_kyc'));

            return {
                rcs: finalRCS,
                outcome: outcome,
                detectionRate: ds.detectionRate || 0,
                falsePositiveRate: ds.falsePositiveRate || 0,
                sarQuality: ds.sarQuality || 0,
                kycProgress: ds.kycProgress || 0,
                performance: outcome,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.alertsAbandoned > 0) {
                return window.mySimulation.t('hint_abandoned');
            }
            if (results.detectionRate < 50) {
                return window.mySimulation.t('hint_low_detection');
            }
            if (results.fpRate > 92) {
                return window.mySimulation.t('hint_high_fp');
            }
            if (results.sarQuality < 2.5) {
                return window.mySimulation.t('hint_low_sar_quality');
            }
            if (state.domainState.backlogRemaining > 600 && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_backlog');
            }
            if (results.detectionRate >= 75 && results.fpRate <= 85) {
                return window.mySimulation.t('hint_good');
            }
            return null;
        }

